"""JPG 112 (printed page 111): roller, profile and chapter conclusions."""
from book import Book, cli


def build():
    b = Book('00_cam_context', 'Кулачковые механизмы. Завершение раздела 7')
    b.page(112, 'Рисунок 7.15. Ролик и конструктивный профиль. Выводы')
    b.figure('fig_7_15', 'Рис. 7.15. Построение центрового профиля при качающемся толкателе: O, A, B; положения A₁…A₁₃, B₀…B₁₃; l₂, r₀, a_w, φ₁у, φ₁с, φ₁р, ω₁ и −ω₁.')
    b.text('Часто в кулачковых механизмах для уменьшения трения при взаимодействии толкателя и кулачка устанавливают ролик (см. рис. 7.14). Радиус ролика выбирают из двух условий: r_рол = (0,25…0,40)r₀ и r_рол < 0,8ρᶜ_min, где ρᶜ_min — минимальный радиус кривизны центрового профиля. Полученное значение r_рол округляют в меньшую сторону согласно ГОСТ 3395–89.')
    b.text('Для получения конструктивного профиля кулачка строят эквидистантный профиль, отстоящий от центрового на расстояние, равное радиусу ролика. Рабочий профиль кулачка есть огибающая к дугам, проведённым из множества точек центрового профиля радиусом ролика (например, для механизма с поступательно движущимся толкателем см. рис. 7.14).')
    b.text('Выводы', heading=True)
    b.text('В разд. 7 пособия рассмотрено проектирование плоского кулачкового механизма, который является составной частью проектируемой машины. Подчёркивается, что проектирование выполняется в два последовательных этапа. На первом этапе решается задача метрического синтеза: определение основных размеров механизма, обеспечивающих заданный закон движения толкателя при ограничениях на угол давления и габаритные размеры. На втором этапе выполняется профилирование кулачка по заданному закону движения толкателя и его основным размерам, найденным в результате метрического синтеза.')
    b.text('Рассмотрены методы решения задач для механизмов с поступательно движущимся толкателем с роликом и с коромысловым остроконечным толкателем.')
    b.text('Описаны численные методы расчётов основных параметров механизма в системе Mathcad. Приведённые в приложении 6 Mathcad-программы носят учебно-демонстрационный характер, позволяющий уяснить суть предлагаемых методов и выбрать тот, который необходим при решении конкретной задачи курсового проекта.')
    b.text('Приведены графоаналитические методы решения задачи кинематического синтеза. Рекомендуется профилирование выполнять в системе AutoCAD.')
    b.text('Примеры выполнения четвёртого листа курсового проекта приведены в приложении 7 (см. Л4.1_П6, Л4.2).')
    b.note('Рис. 7.14 и приложение 7 отсутствуют в этом архиве; ссылки сохранены, их содержание не выдумано. Обозначение ρᶜ_min здесь передано как радиус кривизны центрового профиля. Историческая ссылка на стандарт — часть текста книги, а не проверка его нынешней применимости.')
    return b

if __name__ == '__main__': cli(build)
